    caution: "定休日は第一・第三火曜日です。営業時間の案内は時期で変わっているため、出かける前に公式ページの最新情報をご確認ください。",
    action: "東新宿・若松河田方面に行く機会があれば、深夜営業を生かして仕事帰りの一湯にも使えます。訪問したらサ印帳で押印を。",
