        text: "2026年2月9日、JR高輪ゲートウェイ駅に直結するニュウマン高輪 Northの5階に「高輪SAUNAS」がグランドオープンしました。所在地は東京都港区高輪2丁目21-1です。運営は渋谷の人気施設「渋谷SAUNAS」と同じ株式会社TOYOKEで、総合プロデュースは『サ道』の著者であるタナカカツキが手がけています。コンセプトは「都市での休息と回復」。駅直結の商業施設の中に、仕事帰りや休日に立ち寄って心身を整えるための都市型リトリートとして設計された施設です。開業から約9か月後の2026年11月には、SAUNACHELIN 2026で第2位に選出されました。"
