        text: "最大の特徴は立地です。高輪ゲートウェイ駅直結のため、雨の日でも外に出ずにたどり着けます。営業時間は11:00から深夜26:00（翌2:00）までで、予約なしで利用できる気軽さも魅力です。館内にはサウナだけでなく、レストラン、ワークスペース、ナップスペース、アロマラボが併設されており、入浴の前後に食事や休憩、軽い仕事まで済ませられる構成になっています。なお、12歳未満は入店できないため、大人向けの落ち着いた利用環境が保たれています。"
