        text: "5室はいずれも方向性が異なります。看板は最大34名が着座できる薪火サウナと、フィンランド産ケロ材を使ったケロ蒸喜乱舞サウナ。江戸時代の戸棚風呂を現代に置き換えた薬草戸棚蒸風呂、濃密な蒸気の瞑想マグマ蒸気、70〜80℃の中温域でじっくり入れる令和遠赤と、熱さの質そのものが室ごとに切り替わる構成です。薪・ケロ・遠赤という異なる熱源を1軒で巡れる施設は、全国的にも多くありません。薪の炎のそばで汗をかく体験、ケロ材の香りに包まれる蒸気、薬草の香りが漂う蒸風呂、蒸気に没入する瞑想空間、遠赤外線でじっくり温まる中温域と、入る順番を考えるだけで一日のプランが組めるほど選択肢が用意されています。熱源の個性で施設を選ぶ時代にあって、その違いを1軒の中で比べられるのは新ブランドならではの強みです。"
