        text: "東京・新橋と赤坂。近距離にある男性専用サウナ2施設がタッグを組む企画「TOKYO SAUNA TRIBE 2026」の第3弾「〜The 3rd STAGE〜」が始まります。テーマは「熱気と冷却で己を鍛え研ぎ澄ませ」。舞台はレンブラントキャビン＆スパ新橋内のライオンサウナ新橋（港区新橋2丁目15−14）と、サウナリゾートオリエンタル赤坂（港区赤坂3丁目19−3）です。2026年春の第1弾、夏の第2弾に続く開催で、共催はレンブラントキャビン＆スパ新橋とセンチュリオンホテルグランド赤坂。特別協賛は花王株式会社、特別協力は株式会社HIDANEです。"
