        type: "p",
        text: "4〜6人で利用できる「コミュニティルーム」もあり、サウナの余韻を味わいながら自然と会話が生まれる空間になっています。一人で静かに自分と向き合う時間も、友人や仲間と余韻を共有する時間も、それぞれに合った過ごし方を選べる施設です。"
