        text: "プレオープンは2026年11月26日（水）から29日（土）まで。グランドオープンは12月1日（火）の予定です。運営は株式会社ニタカ。公式サイトとInstagram、LINEで完成までの過程が発信されています。サウナを入口に、温泉街を歩き、地元の飲食店や温泉、旅館を楽しむ流れをつくることも大きな目的で、街歩きマップの制作や地域事業者との連携も進められています。"
