        type: "p",
        text: "まず11月20日（金）から登場するのが、アルガンオイルとアミノ酸を配合したノンシリコンのボタニカルシャンプーセット「SILLAGE～シアージュ～」です。シリコンを含まず、弱酸性の低刺激アミノ酸配合でしっとりとした洗いあがりに。モロッコ原産のアルガンツリーから採れる希少なアルガンオイルの保湿力と抗酸化作用で、肌荒れや炎症をやわらげる効果が期待できると紹介されています。柑橘系の爽やかで優しい香りが浴場に広がります。"
