        text: "11月24日（火）から26日（木）の3日間は、男女浴場の「彩りの湯」でゆず湯が実施されます。12月の冬至にゆず湯に入るのは、邪気を払い無病息災を願う日本の伝統的な慣習。少し早い冬至の湯で、血行促進と心身の癒やしを、とプレスリリースは説明しています。"
