        text: "2026年の「お風呂の年」は、2025年11月26日に“記念年”として登録されました。全国公衆浴場業生活衛生同業組合連合会、公益社団法人日本サウナ・スパ協会、一般社団法人温浴振興協会、一般社団法人ニッポンおふろ元気プロジェクトなどが協力する「2026 お風呂の年プロジェクト」が制定し、2026年の温浴業界を盛り上げてきました。温泉道場の毎月26日の無料キャンペーンも、その流れの中で続いてきたものです。締めくくりとなる11月26日は、家族でゆっくりとお風呂を楽しみながら、心も体も温まる特別な一日にしてみてください。"
