    "lead": "千葉・香取の農園リゾートTHE FARM内にある「おふろcafe かりんの湯」が、2026年11月26日（木）の「いい風呂の日」に、会員ポイント10倍と入会料無料、回数券の特典を実施します。当日はスタッフ同士のコラボアウフグースも全4回開催。2026年は西暦の下3桁が「026（おふろ）」と読める「お風呂の年」で、「1126（いいふろ）」と重なる特別な一日です。公式の案内をもとに、当日の特典を整理しました。",
