    "title": "3店舗めぐって2,000円。湯楽の里・喜楽里の全22店舗で「ご湯印めぐり手形」と新生姜コラボのいい風呂キャンペーン",
    "lead": "日帰り温浴施設「湯楽の里」「喜楽里」が、2026年11月21日（土）から29日（日）まで、首都圏1都6県の全22店舗で「いい風呂キャンペーン」を開催しています。目玉は、好きな3店舗を利用できるヒノキの「ご湯印めぐり手形」（1枚2,000円）。岩下の新生姜とのコラボレーションも6年目を迎え、11月26日の「いい風呂の日」には香り湯とアプリのスタンプ3倍が重なります。公式の特設ページをもとに、キャンペーンの中身を整理しました。",
