    "lead": "天然温泉「仙台コロナの湯」（宮城県仙台市）が、2026年11月19日（木）にリフレッシュオープンしました。男性サウナにはオートロウリュと連動する送風機、男女のサウナには連動する照明演出を新設。洗い場のパーテーションや水飲み場の冷却装置など、細部の快適さも底上げされています。11月30日（月）までの記念イベントとあわせて、運営会社コロナワールドの公式お知らせをもとに整理しました。",
