        "text": "仙台コロナの湯の営業時間は朝6:00から翌2:00まで（最終受付は翌1:30）と長く、仕事前や仕事帰りにも組み込めます。入泉料は大人（中学生以上）が平日1,200円・土日祝1,400円で、会員は平日1,100円・土日祝1,300円です（いずれも別途入湯税70円）。天然温泉の大浴場と岩盤浴エリア「フォーレスト」を備え、今回の連動送風機と照明演出でサウナの楽しみ方が一段増えました。仙台市内から通える大型温浴として、リフレッシュ後の姿を確認しに行く価値があります。記念イベントが終わる11月30日までの訪問がおすすめです。"
