    "lead": "群馬県高崎市に2026年12月グランドオープン予定の「COCOFURO plus みさと温泉」について、2種類のサウナと多彩なお風呂、料金と営業時間が公式サイトで公開されました。静けさの溶岩サウナ「蒸禅」と、音楽に合わせてロウリュが広がるミュージックロウリュサウナ。源泉は箕郷元湯で、入浴料金は大人平日880円からです。正式な開業日は未発表のため、その点も含めて公式の案内を整理しました。",
