        "text": "お風呂は、天然温泉と天然地下水を生かした多彩なラインナップです。公式サイトに並ぶのは、源泉炭酸泉、生源泉風呂、超熱湯、深水風呂、不感寝ころび湯、露天のくつろぎ湯、生源泉壺湯、壺水風呂、電気風呂などです。源泉は箕郷元湯で、泉質はナトリウム-塩化物・炭酸水素塩温泉（低張性・弱アルカリ性・高温泉）、源泉温度は47.4℃と案内されています。熱さも深さも入り方も選べる浴槽をそろえる方針で、サウナ後の深水風呂まで含めて「どの湯が好きか」を探せる施設になりそうです。なお、浴槽の名称や湯温などの詳細は、開業に向けて最終調整が進められていると公式は注記しています。"
