    "title": "月会費7,678円で個室サウナもゴルフも使い放題。FIT-EASY トナリエ久里浜店が12月8日にグランドオープン、プレオープンは11月28日から",
    "lead": "フィットイージー株式会社が運営するアミューズメントフィットネスクラブ「FIT-EASY トナリエ久里浜店」が、2026年12月8日（火）に神奈川県横須賀市でグランドオープンします。神奈川県5店舗目、横須賀市初出店で、11月28日（土）から12月7日（月）まではプレオープン期間です。完全個室の「FIT-SAUNA」は水風呂とととのいスペースを備え、サウナのみの利用もできます。月会費7,678円（税込）の中に、シミュレーションゴルフや健康カラオケ、高濃度酸素ルームまで含まれます。運営会社のプレスリリースと店舗の公式ページをもとに、開業の中身とお得な入会条件を整理しました。",
