    "title": "イヨシコーラの香りと爆風メガ熱波。ニフティ温泉6連覇の美楽温泉 SPA-HERBSが11月26日「いい風呂の日」限定で年末感謝祭",
    "lead": "埼玉県さいたま市の「美楽温泉 SPA-HERBS」が、2026年11月26日（木）の「いい風呂の日」に合わせて、1日限定の『スパハーブス年末感謝祭』を開催します。「初めて熱波を受ける方大歓迎！」をテーマに、クラフトコーラ「イヨシコーラ」のアロマを使ったアウフグースや、夜の「爆風体感！メガ熱波」、サウンドヒーリングなどが一日を通して並びます。ニフティ温泉年間ランキング2025で全国総合1位を6年連続で受賞した施設の、年に一度の熱波の日を公式発表から整理しました。",
    "publishedAt": "2026-11-23",
