    "title": "『ゴールデンカムイ』が極楽湯・RAKU SPAに「湯上黄金郷」。12月10日からコラボ風呂4種と鶴見中尉の鶴見ジャック、描き下ろしサウナイラストも登場",
    "lead": "TVアニメ『ゴールデンカムイ』と極楽湯・RAKU SPAグループのコラボキャンペーン「湯上黄金郷」が、2026年12月10日（木）から2027年1月5日（火）まで、グループ13店舗で開催されます。キャラクターをイメージしたコラボ風呂は4種類、入館時にもらえる限定タオルの「プラスセット」、コースター付きのコラボメニューに、RAKU SPA 鶴見を鶴見中尉がジャックする特別イベントまで。浴衣姿に加えてサウナイラストも描き下ろしで登場します。公式発表とコラボ特設サイトをもとに整理しました。",
