        "type": "p",
        "text": "描き下ろしイラストやオリジナルデフォルメイラストを使ったコラボグッズは、開催店舗のほか、オンラインショップ「GK Store」でも12月10日12時から2027年1月11日23時59分まで販売されます。店舗でコラボグッズを2,000円（税込）購入するごとに、和紙風ステッカー（A全9種／B全8種からランダム）が1枚もらえる店舗限定特典もあります。12月10日から13日は店舗での購入制限期間で、制限の内容は極楽湯／RAKU SPA公式Xで案内されます。また、両作品の公式Xをフォローし、ハッシュタグ「#湯上黄金郷」をつけて投稿した画面を受付で提示すると、ポストカードが1枚もらえるX投稿キャンペーンも実施されます。"
