    "lead": "さいたま市の「美楽温泉 SPA-HERBS」が、2026年12月1日（火）から年末特別企画「忘年温活」を順次開催します。目玉は12月22日（火）の冬至当日に、本物のゆずを露天風呂に浮かべる「生ゆず湯」。12月1日から13日までは最初の1杯が特別価格になる「フライング忘年会」、週末ごとに変わる「イベント風呂」、レストランの冬限定メニュー「冬の味覚祭」と、温まって、食べて、飲む企画がそろいます。運営会社のプレスリリースをもとに、12月の予定を整理しました。",
