        "type": "p",
        "text": "12月の目玉は、12月22日（火）の冬至当日に実施される「生ゆず湯」です。地元のお客様から譲り受けた本物のゆずを露天風呂に浮かべて開催されます。入浴剤ではなく生のゆずを使うため、湯船に近づく前から柑橘の香りが漂う、本格的な冬至の湯です。冬至にゆず湯に入ると風邪をひかないと言い伝えられてきた日本の習慣を、大型施設の露天風呂で体験できる一日限りの機会です。ゆずの実を湯に浮かべる風習は、冬至の時期に旬を迎えるゆずの強い香りで邪気を払う意味も込められてきました。当日は火曜日のため、週末の混雑を避けたい人にも狙い目です。"
