    "caution": "コロナの湯 安城店は改装工事のため、2026年12月17日まで休業中です。公式サイトに掲載の料金・営業時間は、リニューアル後に変更される場合があります。刺青・タトゥー（タトゥーシールを含む）のある方は利用できません。再開後の最新情報は公式サイトで確認してください。",
