        "text": "岡崎南店の目玉は、サウナと岩盤浴の2つの温活設備です。ととのいスペースを備えた完全個室サウナは男性専用で、サウナでしっかり身体を温めたあとはゆったりと休息し、トレーニング後のリカバリーに活用できます。店舗公式ページによれば、サウナの利用は原則としてスタッフ駐在時間（11:00〜20:00）のみです。もう一つの個室岩盤浴は女性専用で、岡崎市では初めての導入です。人目を気にすることなく、自分だけの空間でじっくり身体の芯から温まることができるとしています。岩盤浴の利用も、原則としてスタッフ駐在時間（11:00〜20:00）のみです。",
        "type": "p"
