        "text": "オープニングキャンペーンとして、早期に入会した人には、入会金3,300円（税込）と事務手数料2,200円（税込）、12月分（日割）と2027年1月分の月会費が無料になります。さらに、水素水サーバーを2カ月無料で使うことができます。12月14日までに入会すると「永久割」として、月会費が永久に550円（税込）割引になります。店舗公式ページによれば、永久割の適用には入会手続きの完了が必要で、入会から3カ月の在籍が必要です。あわせて、11月30日（月）から12月31日（木）までの「のりかえキャンペーン」では、他ジムの在籍証明書や退会届（3カ月以内の在籍が確認できるもの）を提示すると、ギフトカード2,000円分がプレゼントされます。ギフトカードの受け取り期間は2027年1月11日から2月28日までで、スタッフタイム内での受け取りです。",
