        "text": "夕刻には、宿泊者だけのために設けられた12席のカウンターレストラン「Restaurant UZU」へ。コースの名前は「一会」で、25,000円／名（税込・サービス料別）です。営業は17:00と19:45の2部制で、外来利用はできません。ペアリングは、ワイン12,000円、アルコール8,000円、ノンアルコール8,000円です。淡路島は、古くから朝廷に食材を献上した「御食国（みけつくに）」のひとつで、漁師や農家をはじめとする生産者との関係を大切にしながら、島の恵みをできる限り新鮮なまま料理へとつないでいます。翌朝の朝食は、ホテルから専用車で約2分の、阿万の海を望む崖の上に建つ「TRATTORIA amarancia」にて。淡路マスとアボカドトースト、サラダプレート、アメリカンブレックファーストの3種類からメインを選ぶスタイルです。",
