        "text": "ホテルの周辺には約30分のトレッキングコースが整備され、海を見渡すベンチを目指して歩くほか、朝の澄んだ空気のなかで行うYOGAや、敷地内の草花を摘んでその日のうちに蒸留する、自分だけのアロマウォーターづくりも楽しめます。さらに足を延ばして、地元農家での収穫体験や、小さな漁港を訪ねる漁師飯体験へ行くこともできます。アクセスは、神戸淡路鳴門自動車道「西淡三原IC」から約25分で、TRATTORIA amarancia専用駐車場に駐車したあと、ホテル専用車で約2分です。神戸三宮からは高速バス「南あわじ福良線」で福良へ行き、福良バス停からタクシーで約25分です。ホテル近隣にはヘリポートもあり、利用について相談できます。",
