        "text": "saunahouseは、男女同スペックで、通常はそれぞれ別フロアを利用するサウナ施設です。12月25日（金）・26日（土）の「シェアサウナDAY」では、女性フロアが男女共有となり、水着着用で男女一緒にサウナの魅力を体感できます。当日はサウナ室内を含めて会話ができ、普段はひとりや男女フロアそれぞれで楽しんでいる人も、大切な人や仲間とともにサウナの楽しさをシェアしながら過ごせます。男性フロアは通常営業のため、男性1人や男性のみのグループは、男性フロアの利用となります。",
