  "lead": "富士急行線の下吉田駅に、引退した鉄道車両を活用した日本初の常設サウナ施設「サ電（SADEN）」が、2026年12月中旬に開業します。車両は1000系1001号編成。普通列車サウナ、寝台列車サウナ、水風呂列車の3つの車両空間を、列車を旅するように巡ります。料金・営業時間・予約方法は11月下旬に発表予定で、現時点では未公表です。公式サイトと富士急行の発表をもとに整理しました。",
