        "text": "参加費は無料ですが、別途施設の入館料が必要です。イベント内容や開催時間は変更となる場合があります。発表では、体調に合わせて無理のない範囲で利用することと、サウナ・入浴前後には十分な水分補給をするよう呼びかけています。12月1日と10日の2日間だけの開催で、ハーバルアウフグースは1日2回だけです。昼の回に参加するなら13時か16時、夜の熱いサウナとアウフグースを楽しむなら20時に合わせるのが目安です。詳細は施設の公式サイトで確認してください。",
