    "sourcesCheckedAt": "2026-11-27",
    "status": "published",
    "title": "昼は70℃のハーブ蒸気、夜は85℃の本気サウナ。おふろcafé かりんの湯「Mellow Sauna Day」は12月1日・10日",
    "updatedAt": "2026-11-27"
