        "text": "オープニングキャンペーンでは、入会金（顔認証ID発行料3,300円）・事務手数料（2,200円）・12月分月会費（日割り）・2027年1月分月会費・水素水サーバー2ヶ月分が無料になります。店舗公式ページによれば、今なら最大20,856円（税込）分お得だとしています。さらに、11月30日までの入会で「永久割」が適用され、月会費が永久に550円（税込）割引になります。ただし永久割には入会から3ヶ月間の在籍が必要で、3ヶ月未満で退会する場合は退会手数料として1ヶ月分の月会費がかかります。キャンペーンの内容や条件は予告なく変更になる場合があるため、入会前に公式ページで最新の条件を確認してください。",
        "type": "p"
