        "text": "店舗は〒261-0001 千葉県千葉市美浜区幸町1丁目26-4、有賀園ゴルフ千葉店の2階・3階です。共用駐車場を52台備え、京成千葉線の西登戸駅からは徒歩約10分です。プレオープン期間（11月18日〜11月30日、10:00〜21:00）は予約なしで無料見学ができるため、グランドオープン前に設備を確かめたい人はこの期間の見学がおすすめです。見学はスタッフ勤務時間帯（10時〜20時）に店舗へ行き、見学したい旨を伝えると案内してもらえます。",
